"""产物页码裁剪（v2.3.32）。

pdf2zh 的 pages 参数语义是「只翻这些页，但输出整个文档」。用户选「仅首页」后
拿到的是 24 页的 PDF——第 1 页中文、其余 23 页还是英文原文。用户翻到后面看到
英文就以为「没翻译」，看到 24 页就以为「全部都在」。

这里在翻译结束后把产物裁成只含用户选的页，让「仅首页」真的只出首页。

页码映射：
* mono / side_by_side：每个原始页对应产物里 1 页 → 直接保留 pages。
* dual：原文、译文交替（第 0 页原文、第 1 页译文、第 2 页原文…）→ 每个原始页
  p 对应产物里的 [2p, 2p+1]。
"""

from __future__ import annotations

import logging
import os

logger = logging.getLogger(__name__)


def crop_to_pages(path: str, pages, kind: str) -> bool:
    """把产物裁剪成只含 pages 指定的页（0-indexed）。

    :param pages: 用户选的原始页码列表（0-indexed）；None 或空表示全部，不裁剪。
    :param kind: "mono" / "side_by_side" / "dual"
    :return: 是否真的做了裁剪
    """
    if not pages or not path or not os.path.exists(path):
        return False
    try:
        import fitz
        pages = sorted({int(p) for p in pages})
        doc = fitz.open(path)
        n = doc.page_count
        if kind == "dual":
            keep = []
            for p in pages:
                keep += [2 * p, 2 * p + 1]
        else:
            keep = list(pages)
        keep = [k for k in keep if 0 <= k < n]
        if not keep:
            doc.close()
            return False
        if len(keep) == n:          # 选的就是全部，无需裁剪
            doc.close()
            return False
        doc.select(keep)            # 只保留这些页并按 keep 顺序重排
        tmp = path + ".crop.pdf"
        doc.save(tmp, garbage=3, deflate=True)
        doc.close()
        os.replace(tmp, path)
        logger.info("产物裁剪 %s: %d 页 → %d 页", os.path.basename(path), n, len(keep))
        return True
    except Exception as e:                      # noqa: BLE001 — 裁剪失败不该毁掉翻译
        logger.warning("产物页码裁剪失败（保留完整产物）: %s: %s", type(e).__name__, e)
        try:
            _t = path + ".crop.pdf"
            if os.path.exists(_t):
                os.remove(_t)
        except Exception:
            pass
        return False


# ── 源 PDF 修复（v2.3.39，issue #35 后续）────────────────────────────────────
# 有些 PDF 内部有坏掉的对象（MuPDF 报 "cannot parse object (2 0 R)" 之类）：能打开、能预览、
# 文字也读得出来，但一另存就失败。pdf2zh 翻译开头要先把原文另存一份，于是整篇都翻不了，
# 用户只看到一串 MuPDF 报错。坏对象往往不在页面用到的路径上（孤立对象、元数据等），
# 修复后不影响页面内容。


class SourcePdfError(RuntimeError):
    """源 PDF 内部损坏、自动修复也没成功（文案直接给用户看）。"""


def repair_pdf_bytes(raw: bytes):
    """检查源 PDF 能否正常另存，不能就修复。

    能正常另存 → (None, "")，调用方照常用原文件；
    另存失败 → 依次尝试 ① pikepdf(qpdf) 修复：保留书签、元数据、链接；
    ② 新建文档只复制页面用到的对象：坏掉的孤立对象被丢掉，书签另行复制（失败就丢）。
    成功返回 (修好的字节, "pikepdf" / "rebuild")；都不行抛 SourcePdfError。
    """
    import io
    import pymupdf

    try:
        pymupdf.open(stream=raw).tobytes()
        return None, ""
    except Exception as e:
        first_err = e
    logger.warning(f"源 PDF 另存失败（{first_err}），尝试修复")

    try:
        import pikepdf
        buf = io.BytesIO()
        with pikepdf.open(io.BytesIO(raw)) as p:
            p.save(buf)
        fixed = buf.getvalue()
        pymupdf.open(stream=fixed).tobytes()
        return fixed, "pikepdf"
    except Exception as e:
        logger.warning(f"pikepdf 修复失败: {e}")

    try:
        src = pymupdf.open(stream=raw)
        doc = pymupdf.open()
        doc.insert_pdf(src)
        try:
            doc.set_toc(src.get_toc())
        except Exception:
            pass
        fixed = doc.tobytes()
        pymupdf.open(stream=fixed).tobytes()
        return fixed, "rebuild"
    except Exception as e:
        logger.warning(f"重建失败: {e}")

    raise SourcePdfError(
        f"这份 PDF 文件内部有损坏的数据（{first_err}），软件自动修复也没成功，所以没法翻译。\n"
        "可以这样处理：用浏览器（Edge / Chrome）打开这份 PDF → 打印 → 打印机选「另存为 PDF」"
        "（或「Microsoft Print to PDF」），然后翻译另存出来的新文件；或者从期刊网站重新下载一次再试。")


def ensure_resaveable_pdf(path: str) -> str:
    """修复 path 指向的 PDF 并就地写回。正常文件不动、返回 ""；修过返回所用办法。
    只能传软件自己的副本（如 pdf2zh_files 里的拷贝），不要传用户的原文件。"""
    with open(path, "rb") as f:
        raw = f.read()
    fixed, how = repair_pdf_bytes(raw)
    if fixed is not None:
        tmp = path + ".repairing"
        with open(tmp, "wb") as f:
            f.write(fixed)
        os.replace(tmp, path)
        logger.info(f"已修复源 PDF（{how}）: {path}")
    return how
